import java.util.ArrayList;
 import java.util.Iterator; 
 import java.util.List; 
 import sailpoint.object.Filter; 
 import sailpoint.object.Identity; 
 import sailpoint.object.QueryOptions;
  // ---------------- configuration ---------------- 
  String NEW_PASSWORD = "xyzzy";
   //----------------------------------------------- 
   // IIQ stores the login password encrypted; encrypt the cleartext first. 
   String encrypted = context.encrypt(NEW_PASSWORD); 
   // 1) Collect ids of all real (non-workgroup) identities via a light projection search. 
   QueryOptions qo = new QueryOptions();
    qo.addFilter(Filter.eq("workgroup", new Boolean(false)));
     List ids = new ArrayList(); 
     Iterator rows = context.search(Identity.class, qo, "id"); 
     while (rows.hasNext()) 
     { 
        ids.add((String) ((Object[]) rows.next())[0]);
         } 
        // 2) Fetch each identity and set the password, committing in batches.
         int updated = 0;
          for (int i = 0; i < ids.size(); i++) { 
            Identity identity = context.getObjectById(Identity.class, (String) ids.get(i));
             if (identity == null) continue;
              identity.setPassword(encrypted); 
              identity.setPasswordExpiration(null); 
              // test convenience: no forced reset at next login 
              context.saveObject(identity); updated++; 
              if (updated % 100 == 0) { 
                context.commitTransaction();
                 context.decache(); 
                 } 
                 } 
                 context.commitTransaction(); 
    return "Password set on " + updated + " identities.";
